import { anthropic } from "@ai-sdk/anthropic";
import { streamText, type ModelMessage, stepCountIs } from "ai";
import { SYSTEM_PROMPT } from "./prompt";
import { ecommerceToolset } from "./tools";

export function ecommerceAgent(messages: ModelMessage[]) {
  return streamText({
    model: anthropic("claude-sonnet-4-5-20250929"),
    system: SYSTEM_PROMPT,
    messages,
    tools: ecommerceToolset,
    stopWhen: [stepCountIs(25)],
  });
}

import { ToolSet } from "ai";
import { mapStoreTool } from "./map-store";
import { discoverProductsTool } from "./discover-products";
import { inferProductSchemaTool } from "./infer-product-schema";
import { extractProductsTool } from "./extract-products";
import { saveCatalogTool } from "./save-catalog";

export const ecommerceToolset = {
  map_store: mapStoreTool,
  discover_products: discoverProductsTool,
  infer_product_schema: inferProductSchemaTool,
  extract_products: extractProductsTool,
  save_catalog: saveCatalogTool,
} as ToolSet;

import { InferUITools, UIMessage } from "ai";
import { ecommerceToolset } from "./toolset";

type EcommerceTools = InferUITools<typeof ecommerceToolset>;

export type EcommerceUIMessage = UIMessage<never, never, EcommerceTools>;

import * as fs from "fs";
import * as path from "path";
import FirecrawlApp from "@mendable/firecrawl-js";

export const ECOMMERCE_AGENT_BASE_DIR = path.join(
  process.cwd(),
  "data",
  "ecommerce-agent.local"
);

/** Default commerce fields for extract_products when no schema is provided. */
export const DEFAULT_PRODUCT_SCHEMA = {
  type: "object",
  properties: {
    title: { type: "string", description: "Product title or name" },
    sku: { type: "string", description: "Product SKU or ID" },
    description: { type: "string", description: "Product description" },
    price: { type: "string", description: "Current price" },
    currency: { type: "string", description: "Currency code or symbol" },
    compare_at_price: {
      type: "string",
      description: "Original or compare-at price before discount",
    },
    in_stock: { type: "boolean", description: "Whether the product is in stock" },
    availability: { type: "string", description: "Stock / availability text" },
    category: { type: "string", description: "Product category" },
    image_url: { type: "string", description: "Primary product image URL" },
    rating: { type: "number", description: "Average customer rating" },
    review_count: { type: "number", description: "Number of reviews" },
    variants: {
      type: "array",
      description: "Product variants such as size or color",
      items: {
        type: "object",
        properties: {
          name: { type: "string", description: "Variant dimension name" },
          value: { type: "string", description: "Variant value" },
        },
      },
    },
    url: { type: "string", description: "Canonical product URL" },
  },
} as const;

export type ProductSchema = {
  type: "object";
  properties: Record<
    string,
    {
      type: string;
      description?: string;
      items?: unknown;
    }
  >;
};

function ensureDir(dirPath: string) {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true });
  }
}

function safeFileName(input: string) {
  return input.toLowerCase().replace(/[^a-z0-9-_]+/g, "-");
}

export function getFirecrawlClient() {
  const apiKey = process.env.FIRECRAWL_API_KEY;
  if (!apiKey) {
    throw new Error(
      "FIRECRAWL_API_KEY is required. Get a key at https://www.firecrawl.dev/app/api-keys"
    );
  }
  return new FirecrawlApp({ apiKey });
}

export function normalizeUrl(url: string) {
  const trimmed = url.trim();
  if (!trimmed) {
    throw new Error("URL is required.");
  }
  if (!trimmed.startsWith("http://") && !trimmed.startsWith("https://")) {
    return `https://${trimmed}`;
  }
  return trimmed;
}

/** Resolve a user path inside the ecommerce workspace; reject traversal. */
export function resolveWorkspacePath(filePath: string) {
  ensureDir(ECOMMERCE_AGENT_BASE_DIR);
  const base = path.resolve(ECOMMERCE_AGENT_BASE_DIR);
  const fullPath = path.resolve(base, filePath);
  if (!fullPath.startsWith(base + path.sep) && fullPath !== base) {
    throw new Error(
      `Access denied: path "${filePath}" is outside the ecommerce workspace.`
    );
  }
  return fullPath;
}

export function writeWorkspaceFile(
  filePath: string,
  contents: string | Buffer
) {
  const fullPath = resolveWorkspacePath(filePath);
  ensureDir(path.dirname(fullPath));
  fs.writeFileSync(fullPath, contents);
  return path.relative(ECOMMERCE_AGENT_BASE_DIR, fullPath);
}

export function saveArtifact(folder: string, fileName: string, payload: unknown) {
  const relative = path.join(folder, fileName);
  const body =
    typeof payload === "string" ? payload : JSON.stringify(payload, null, 2);
  return writeWorkspaceFile(relative, body);
}

export function buildTaskMetadata(taskName: string) {
  return {
    task_name: safeFileName(taskName),
    created_at: new Date().toISOString(),
  };
}

/** Shopify/Woo/custom product paths + Amazon /dp/ASIN and /gp/product/. */
const PRODUCT_PATH_HINTS =
  /\/(products?|product|item|sku|gp\/product)(\/|$)|\/dp\/[A-Z0-9]{8,}(\/|$)|\/gp\/aw\/d\/[A-Z0-9]{8,}(\/|$)/i;
const CATEGORY_PATH_HINTS =
  /\/(collections?|categor(y|ies)|shop|catalog|b\/|zgbs|Best-Sellers)(\/|$)|\/s(\/|$|\?)/i;
const NON_PRODUCT_HINTS =
  /\/(cart|checkout|account|login|signup|blog|news|about|contact|policy|privacy|terms|faq|help|customer|gp\/cart|gp\/css)(\/|$)/i;

export type UrlClass = "product" | "category" | "other";

export function classifyStoreUrl(url: string): UrlClass {
  try {
    const parsed = new URL(url);
    const pathname = parsed.pathname;
    const search = parsed.search;
    if (NON_PRODUCT_HINTS.test(pathname)) return "other";
    // Amazon search / browse nodes
    if (
      pathname === "/s" ||
      pathname.startsWith("/s/") ||
      pathname.includes("/b/") ||
      search.includes("node=")
    ) {
      return "category";
    }
    if (PRODUCT_PATH_HINTS.test(pathname)) return "product";
    if (CATEGORY_PATH_HINTS.test(pathname)) return "category";
    return "other";
  } catch {
    return "other";
  }
}

/** Normalize Amazon product URLs to canonical /dp/ASIN form when possible. */
export function canonicalizeProductUrl(url: string): string {
  try {
    const parsed = new URL(url);
    const dp = parsed.pathname.match(/\/dp\/([A-Z0-9]{8,})/i);
    if (dp) {
      return `${parsed.origin}/dp/${dp[1]}`;
    }
    const gp = parsed.pathname.match(/\/gp\/(?:product|aw\/d)\/([A-Z0-9]{8,})/i);
    if (gp) {
      return `${parsed.origin}/dp/${gp[1]}`;
    }
    // Strip tracking query for Shopify-style product URLs
    if (/\/products?\//i.test(parsed.pathname)) {
      parsed.search = "";
      parsed.hash = "";
      return parsed.toString();
    }
    return url;
  } catch {
    return url;
  }
}

/**
 * Pull product-like hrefs from a scraped page (Firecrawl `links` format or markdown).
 * Used when map_store fails on JS-heavy marketplaces (Amazon category/search pages).
 */
export function extractProductLinksFromPage(
  links: unknown,
  options?: { limit?: number; sameHostAs?: string }
): string[] {
  const limit = options?.limit ?? 50;
  const raw: string[] = [];

  if (Array.isArray(links)) {
    for (const item of links) {
      if (typeof item === "string") raw.push(item);
      else if (item && typeof item === "object" && "url" in item) {
        const u = (item as { url?: unknown }).url;
        if (typeof u === "string") raw.push(u);
      } else if (item && typeof item === "object" && "href" in item) {
        const u = (item as { href?: unknown }).href;
        if (typeof u === "string") raw.push(u);
      }
    }
  }

  let sameHost: string | undefined;
  if (options?.sameHostAs) {
    try {
      sameHost = new URL(normalizeUrl(options.sameHostAs)).hostname;
    } catch {
      sameHost = undefined;
    }
  }

  const seen = new Set<string>();
  const products: string[] = [];

  for (const href of raw) {
    let absolute: string;
    try {
      absolute = normalizeUrl(href);
    } catch {
      continue;
    }
    try {
      const host = new URL(absolute).hostname;
      if (sameHost && host !== sameHost && !host.endsWith(`.${sameHost}`)) {
        continue;
      }
    } catch {
      continue;
    }
    if (classifyStoreUrl(absolute) !== "product") continue;
    const canonical = canonicalizeProductUrl(absolute);
    if (seen.has(canonical)) continue;
    seen.add(canonical);
    products.push(canonical);
    if (products.length >= limit) break;
  }

  return products;
}

export function classifyUrls(urls: string[]) {
  const product_urls: string[] = [];
  const category_urls: string[] = [];
  const other_urls: string[] = [];

  for (const url of urls) {
    const kind = classifyStoreUrl(url);
    if (kind === "product") product_urls.push(url);
    else if (kind === "category") category_urls.push(url);
    else other_urls.push(url);
  }

  return {
    total: urls.length,
    product_urls,
    category_urls,
    other_urls,
    product_count: product_urls.length,
    category_count: category_urls.length,
    other_count: other_urls.length,
  };
}

/** Infer a commerce-first schema from sample page markdown/html. */
export function inferProductSchemaFromContent(content: string): ProductSchema {
  const schema: ProductSchema = {
    type: "object",
    properties: {},
  };

  const patterns: Array<{
    regex: RegExp;
    field: string;
    type: string;
    description: string;
  }> = [
    {
      regex: /\$[\d,]+\.?\d*/g,
      field: "price",
      type: "string",
      description: "Product price",
    },
    {
      regex: /sku[:\s]*([A-Za-z0-9-_]+)/gi,
      field: "sku",
      type: "string",
      description: "Product SKU",
    },
    {
      regex: /in\s+stock|out\s+of\s+stock|availability/gi,
      field: "availability",
      type: "string",
      description: "Stock availability",
    },
    {
      regex: /rating[:\s]*(\d+\.?\d*)|(\d+\.?\d*)\s*stars?/gi,
      field: "rating",
      type: "number",
      description: "Customer rating",
    },
    {
      regex: /category[:\s]*([^,\n]+)/gi,
      field: "category",
      type: "string",
      description: "Product category",
    },
    {
      regex: /\!\[[^\]]*\]\(([^)]+)\)|<img[^>]*src="/gi,
      field: "image_url",
      type: "string",
      description: "Product image URL",
    },
  ];

  for (const pattern of patterns) {
    if (pattern.regex.test(content)) {
      schema.properties[pattern.field] = {
        type: pattern.type,
        description: pattern.description,
      };
    }
  }

  const defaults = DEFAULT_PRODUCT_SCHEMA.properties;
  for (const [key, value] of Object.entries(defaults)) {
    if (!schema.properties[key]) {
      schema.properties[key] = {
        type: value.type,
        description: value.description,
        ...("items" in value ? { items: value.items } : {}),
      };
    }
  }

  return schema;
}

export function getDefaultProductSchema(): ProductSchema {
  return JSON.parse(JSON.stringify(DEFAULT_PRODUCT_SCHEMA)) as ProductSchema;
}

/** Convert our schema shape into a JSON Schema object for Firecrawl. */
export function toFirecrawlJsonSchema(schema: ProductSchema) {
  const properties: Record<string, unknown> = {};
  for (const [key, prop] of Object.entries(schema.properties)) {
    if (prop.type === "array") {
      properties[key] = {
        type: "array",
        description: prop.description ?? `${key} field`,
        items: prop.items ?? { type: "string" },
      };
    } else {
      properties[key] = {
        type: prop.type,
        description: prop.description ?? `${key} field`,
      };
    }
  }
  return {
    type: "object",
    properties,
    required: Object.keys(schema.properties),
  };
}

export function productsToCsv(products: Array<Record<string, unknown>>) {
  if (products.length === 0) {
    return "url\n";
  }
  const keys = Array.from(
    products.reduce((set, row) => {
      Object.keys(row).forEach((k) => set.add(k));
      return set;
    }, new Set<string>())
  );
  const escape = (value: unknown) => {
    const text =
      value === null || value === undefined
        ? ""
        : typeof value === "object"
          ? JSON.stringify(value)
          : String(value);
    if (/[",\n]/.test(text)) {
      return `"${text.replace(/"/g, '""')}"`;
    }
    return text;
  };
  const lines = [keys.join(",")];
  for (const row of products) {
    lines.push(keys.map((k) => escape(row[k])).join(","));
  }
  return lines.join("\n") + "\n";
}

export function extractMapLinks(mapResult: unknown): string[] {
  if (!mapResult || typeof mapResult !== "object") return [];
  const result = mapResult as {
    success?: boolean;
    links?: string[];
    data?: string[];
    urls?: string[];
  };
  if (Array.isArray(result.links)) return result.links;
  if (Array.isArray(result.data)) return result.data;
  if (Array.isArray(result.urls)) return result.urls;
  return [];
}

import { tool } from "ai";
import {
  classifyUrls,
  extractMapLinks,
  getFirecrawlClient,
  normalizeUrl,
  saveArtifact,
} from "./core";
import { mapStoreSchema } from "./schema";

export const mapStoreTool = tool({
  description:
    "Map an e-commerce store via Firecrawl sitemap-style discovery. Best for Shopify and open catalogs. For Amazon category/search pages (/b/, /s?), use discover_products instead — map usually returns almost no product URLs.",
  inputSchema: mapStoreSchema,
  execute: async ({
    store_url,
    limit,
    include_subdomains,
    save_map,
  }) => {
    const url = normalizeUrl(store_url);
    const client = getFirecrawlClient();

    const mapResult = await client.mapUrl(url, {
      limit,
      includeSubdomains: include_subdomains,
    });

    if ("success" in mapResult && mapResult.success === false) {
      throw new Error(
        `map_store failed: ${"error" in mapResult ? mapResult.error : "unknown error"}`
      );
    }

    const urls = extractMapLinks(mapResult);
    const analysis = classifyUrls(urls);

    let saved_path: string | undefined;
    if (save_map) {
      const host = (() => {
        try {
          return new URL(url).hostname.replace(/\./g, "-");
        } catch {
          return "store";
        }
      })();
      saved_path = saveArtifact("maps", `${host}-urls.json`, {
        store_url: url,
        mapped_at: new Date().toISOString(),
        ...analysis,
        urls,
      });
    }

    return {
      success: true,
      content: {
        store_url: url,
        ...analysis,
        saved_path,
        sample_product_urls: analysis.product_urls.slice(0, 10),
        sample_category_urls: analysis.category_urls.slice(0, 10),
      },
    };
  },
});

import { tool } from "ai";
import {
  classifyStoreUrl,
  extractProductLinksFromPage,
  getFirecrawlClient,
  normalizeUrl,
  saveArtifact,
} from "./core";
import { discoverProductsSchema } from "./schema";

export const discoverProductsTool = tool({
  description:
    "Scrape a category/search/listing page and extract product URLs from on-page links. Use this instead of map_store for Amazon, Flipkart, and other JS-heavy marketplaces where map returns almost no product URLs.",
  inputSchema: discoverProductsSchema,
  execute: async ({ listing_url, limit, save_map }) => {
    const url = normalizeUrl(listing_url);
    const client = getFirecrawlClient();

    const scrapeResult = await client.scrapeUrl(url, {
      formats: ["links", "markdown"],
      onlyMainContent: false,
      timeout: 60000,
      waitFor: 3000,
    });

    if ("success" in scrapeResult && scrapeResult.success === false) {
      throw new Error(
        `discover_products failed: ${
          "error" in scrapeResult ? scrapeResult.error : "unknown error"
        }`
      );
    }

    const links =
      "links" in scrapeResult && Array.isArray(scrapeResult.links)
        ? scrapeResult.links
        : [];

    // Also harvest markdown hrefs as a fallback
    const markdown =
      "markdown" in scrapeResult && typeof scrapeResult.markdown === "string"
        ? scrapeResult.markdown
        : "";
    const mdHrefs = Array.from(
      markdown.matchAll(/\[[^\]]*\]\((https?:[^)\s]+)\)/g)
    ).map((m) => m[1]);

    const product_urls = extractProductLinksFromPage([...links, ...mdHrefs], {
      limit,
      sameHostAs: url,
    });

    const listing_class = classifyStoreUrl(url);

    let saved_path: string | undefined;
    if (save_map) {
      const host = (() => {
        try {
          return new URL(url).hostname.replace(/\./g, "-");
        } catch {
          return "store";
        }
      })();
      saved_path = saveArtifact("maps", `${host}-listing-products.json`, {
        listing_url: url,
        listing_class,
        discovered_at: new Date().toISOString(),
        product_count: product_urls.length,
        product_urls,
        raw_link_count: links.length + mdHrefs.length,
      });
    }

    return {
      success: true,
      content: {
        listing_url: url,
        listing_class,
        product_count: product_urls.length,
        product_urls,
        sample_product_urls: product_urls.slice(0, 10),
        raw_link_count: links.length + mdHrefs.length,
        saved_path,
        hint:
          product_urls.length === 0
            ? "No product URLs found on this page. Amazon/Flipkart often block scrapers — try a public Shopify collection URL, or pass product /dp/ links directly to extract_products."
            : "Pass these URLs to extract_products next.",
      },
    };
  },
});

import { tool } from "ai";
import {
  getDefaultProductSchema,
  getFirecrawlClient,
  inferProductSchemaFromContent,
  normalizeUrl,
  saveArtifact,
} from "./core";
import { inferProductSchemaSchema } from "./schema";

export const inferProductSchemaTool = tool({
  description:
    "Infer a commerce product schema from a sample product URL (or return the built-in default). Saves under data/ecommerce-agent.local/schemas/ by default.",
  inputSchema: inferProductSchemaSchema,
  execute: async ({ product_url, use_default_schema, save_schema }) => {
    const url = normalizeUrl(product_url);
    let schema = getDefaultProductSchema();
    let source: "default" | "inferred" = "default";
    let sample_preview: string | undefined;

    if (!use_default_schema) {
      const client = getFirecrawlClient();
      const scrapeResult = await client.scrapeUrl(url, {
        formats: ["markdown", "html"],
        onlyMainContent: true,
        timeout: 30000,
        maxAge: 86400000,
      });

      if ("success" in scrapeResult && scrapeResult.success === false) {
        source = "default";
      } else if ("markdown" in scrapeResult || "html" in scrapeResult) {
        const markdown =
          "markdown" in scrapeResult ? scrapeResult.markdown ?? "" : "";
        const html = "html" in scrapeResult ? scrapeResult.html ?? "" : "";
        const content = `${markdown}\n${html}`;
        schema = inferProductSchemaFromContent(content);
        source = "inferred";
        sample_preview = markdown.slice(0, 500);
      }
    }

    let saved_path: string | undefined;
    if (save_schema) {
      const host = (() => {
        try {
          return new URL(url).hostname.replace(/\./g, "-");
        } catch {
          return "store";
        }
      })();
      saved_path = saveArtifact("schemas", `${host}-product.json`, {
        product_url: url,
        source,
        inferred_at: new Date().toISOString(),
        schema,
      });
    }

    return {
      success: true,
      content: {
        product_url: url,
        source,
        schema,
        fields: Object.keys(schema.properties),
        sample_preview,
        saved_path,
      },
    };
  },
});

import { tool } from "ai";
import {
  getDefaultProductSchema,
  getFirecrawlClient,
  normalizeUrl,
  toFirecrawlJsonSchema,
  type ProductSchema,
} from "./core";
import { extractProductsSchema } from "./schema";

type ScrapeRow = {
  url?: string;
  json?: Record<string, unknown>;
  extract?: Record<string, unknown>;
  markdown?: string;
  metadata?: Record<string, unknown>;
  error?: string;
};

function resolveSchema(
  schema?: Record<string, { type: string; description?: string }>
): ProductSchema {
  if (!schema || Object.keys(schema).length === 0) {
    return getDefaultProductSchema();
  }
  const properties: ProductSchema["properties"] = {};
  for (const [key, value] of Object.entries(schema)) {
    properties[key] = {
      type: value.type,
      description: value.description ?? `${key} field`,
      ...(value.type === "array" ? { items: { type: "string" } } : {}),
    };
  }
  return { type: "object", properties };
}

function rowToProduct(row: ScrapeRow, fallbackUrl?: string) {
  const data = (row.json ?? row.extract ?? {}) as Record<string, unknown>;
  const sourceUrl =
    row.url ??
    (typeof row.metadata?.sourceURL === "string"
      ? row.metadata.sourceURL
      : fallbackUrl);
  return {
    ...data,
    url: (typeof data.url === "string" ? data.url : sourceUrl) ?? sourceUrl,
  };
}

export const extractProductsTool = tool({
  description:
    "Batch-scrape product page URLs with a commerce JSON schema via Firecrawl. Prefer 20–50 URLs per call.",
  inputSchema: extractProductsSchema,
  execute: async ({ urls, schema, max_age_ms }) => {
    const normalized = urls.map(normalizeUrl);
    const productSchema = resolveSchema(schema);
    const jsonSchema = toFirecrawlJsonSchema(productSchema);
    const client = getFirecrawlClient();

    const scrapeOptions = {
      formats: ["markdown", "json"] as ("markdown" | "json")[],
      onlyMainContent: true,
      timeout: 60000,
      maxAge: max_age_ms,
      jsonOptions: {
        schema: jsonSchema as unknown as never,
        prompt:
          "Extract e-commerce product fields from this page. Prefer accurate price, SKU, stock, and variants when present.",
      },
    };

    let products: Array<Record<string, unknown>> = [];
    let credits_used: number | undefined;
    let mode: "batch" | "fallback" = "batch";

    try {
      const batchResult = await client.batchScrapeUrls(
        normalized,
        scrapeOptions
      );

      if ("success" in batchResult && batchResult.success === false) {
        throw new Error(
          "error" in batchResult ? String(batchResult.error) : "Batch scrape failed"
        );
      }

      const data =
        "data" in batchResult && Array.isArray(batchResult.data)
          ? (batchResult.data as ScrapeRow[])
          : [];
      products = data.map((row, i) => rowToProduct(row, normalized[i]));
      credits_used =
        "creditsUsed" in batchResult && typeof batchResult.creditsUsed === "number"
          ? batchResult.creditsUsed
          : data.length;
    } catch {
      mode = "fallback";
      const fallback: Array<Record<string, unknown>> = [];
      for (const url of normalized) {
        try {
          const result = await client.scrapeUrl(url, scrapeOptions);
          if ("success" in result && result.success === false) {
            fallback.push({
              url,
              error: "error" in result ? result.error : "failed",
            });
            continue;
          }
          fallback.push(rowToProduct(result as ScrapeRow, url));
        } catch (err) {
          fallback.push({
            url,
            error: err instanceof Error ? err.message : "Scrape failed",
          });
        }
      }
      products = fallback;
      credits_used = fallback.filter((p) => !("error" in p && p.error)).length;
    }

    const ok = products.filter((p) => !p.error);
    const failed = products.filter((p) => p.error);

    return {
      success: true,
      content: {
        mode,
        requested: normalized.length,
        extracted: ok.length,
        failed: failed.length,
        credits_used,
        schema_fields: Object.keys(productSchema.properties),
        products: ok,
        errors: failed,
      },
    };
  },
});

import { tool } from "ai";
import {
  buildTaskMetadata,
  productsToCsv,
  writeWorkspaceFile,
} from "./core";
import { saveCatalogSchema } from "./schema";

export const saveCatalogTool = tool({
  description:
    "Save extracted product catalog as JSON or CSV under data/ecommerce-agent.local/catalogs/.",
  inputSchema: saveCatalogSchema,
  execute: async ({ catalog_name, products, format }) => {
    const meta = buildTaskMetadata(catalog_name);
    const extension = format === "csv" ? "csv" : "json";
    const relativePath = `catalogs/${meta.task_name}.${extension}`;

    const body =
      format === "csv"
        ? productsToCsv(products as Array<Record<string, unknown>>)
        : JSON.stringify(
            {
              catalog_name: meta.task_name,
              created_at: meta.created_at,
              product_count: products.length,
              products,
            },
            null,
            2
          );

    const savedPath = writeWorkspaceFile(relativePath, body);

    return {
      success: true,
      content: {
        path: savedPath,
        format,
        catalog_name: meta.task_name,
        product_count: products.length,
        created_at: meta.created_at,
      },
    };
  },
});
